"use client";

import React, { useRef } from "react";
import { motion, useScroll } from "motion/react";
import { Sparkles, Layers } from "lucide-react";
import { cn } from "@/lib/utils";

function TrackItem({ index }: { index: number }) {
  const ref = useRef<HTMLDivElement>(null);
  const { scrollYProgress } = useScroll({
    target: ref,
    offset: ["end end", "start start"],
  });

  return (
    <div className="flex items-center justify-center py-12">
      <div
        ref={ref}
        className="relative flex h-52 w-64 items-center justify-center rounded-3xl border border-dashed border-pink-500/40 bg-neutral-50 dark:bg-neutral-900/60 shadow-lg p-6"
      >
        {/* Sticky Tracking SVG Progress Dial */}
        <figure className="absolute -left-12 -top-6 h-16 w-16 select-none pointer-events-none">
          <svg
            className="h-16 w-16 -rotate-90 stroke-pink-500 overflow-visible"
            viewBox="0 0 100 100"
          >
            {/* Background ghost circle */}
            <circle
              cx="50"
              cy="50"
              r="30"
              pathLength="1"
              className="fill-none stroke-neutral-200 dark:stroke-neutral-800 opacity-40"
              strokeWidth="6"
            />
            {/* Animated foreground indicator */}
            <motion.circle
              cx="50"
              cy="50"
              r="30"
              pathLength="1"
              className="fill-none stroke-pink-500"
              strokeWidth="6"
              strokeDashoffset="0"
              style={{
                pathLength: scrollYProgress,
              }}
            />
          </svg>
        </figure>

        <div className="flex flex-col items-center text-center gap-1">
          <span className="text-[10px] font-mono font-bold uppercase tracking-widest text-pink-500">
            Node #{index + 1}
          </span>
          <h4 className="text-sm font-bold text-neutral-900 dark:text-neutral-100">
            Viewport Target
          </h4>
          <p className="text-[11px] text-neutral-500">
            Tracks element offset through the visible container
          </p>
        </div>
      </div>
    </div>
  );
}

export function SvgTrackProgress({ className }: { className?: string }) {
  const containerRef = useRef<HTMLDivElement>(null);

  return (
    <div
      data-slot="svg-track-progress"
      className={cn(
        "relative flex flex-col w-full max-w-xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-white dark:bg-neutral-950 shadow-2xl select-none",
        className
      )}
    >
      <div className="sticky top-0 z-20 flex items-center justify-between border-b border-neutral-100 dark:border-neutral-800/80 bg-white/90 dark:bg-neutral-900/90 px-6 py-3.5 backdrop-blur-md">
        <div className="flex items-center gap-2">
          <Layers className="h-4 w-4 text-pink-500" />
          <span className="text-xs font-bold text-neutral-900 dark:text-neutral-100">
            SVG Viewport Tracking
          </span>
        </div>
        <div className="flex items-center gap-1 text-[11px] font-mono text-neutral-500">
          <Sparkles className="h-3.5 w-3.5 text-purple-400" />
          <span>Scroll inside container</span>
        </div>
      </div>

      <div
        ref={containerRef}
        className="h-full overflow-y-auto px-6 divide-y divide-neutral-100 dark:divide-neutral-800/40"
      >
        {Array.from({ length: 6 }).map((_, i) => (
          <TrackItem key={i} index={i} />
        ))}
      </div>
    </div>
  );
}
